const CACHE_TTL_MINUTES = 15;
const METRICS_CACHE_KEY = "post-list-v2"; // v2: impressionCount → view_count
const MAX_LOOKBACK_DAYS = 365;

function formatDateYmd(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function defaultDateRange(): { start: string; end: string } {
  const end = new Date();
  const start = new Date();
  start.setDate(start.getDate() - 29);
  return { start: formatDateYmd(start), end: formatDateYmd(end) };
}

function parseYmd(ymd: string): Date | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(ymd.trim());
  if (!m) return null;
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return Number.isNaN(d.getTime()) ? null : d;
}

function clampDateRange(startYmd: string, endYmd: string, now = new Date()) {
  const minStart = new Date(now);
  minStart.setDate(minStart.getDate() - MAX_LOOKBACK_DAYS);
  let start = parseYmd(startYmd) ?? minStart;
  let end = parseYmd(endYmd) ?? now;
  if (start.getTime() < minStart.getTime()) start = minStart;
  if (start.getTime() > end.getTime()) start = end;
  return { start: formatDateYmd(start), end: formatDateYmd(end) };
}

export async function handleLinkedInMetrics(
  admin: SupabaseClient,
  userId: string,
  body: Record<string, unknown>,
): Promise<Response> {
  try {
    const platformForbidden = requireLinkedInContentPlatformConfigured();
    if (platformForbidden) return platformForbidden;

    const organizationId = String(body.organization_id ?? "").trim();
    if (!organizationId) return linkedinContentJson({ error: "Missing organization_id" }, 400);

    const orgForbidden = await requireActiveOrg(admin, userId, organizationId);
    if (orgForbidden) return orgForbidden;

    const dr = defaultDateRange();
    const rawStart = String(body.date_start ?? dr.start).trim();
    const rawEnd = String(body.date_end ?? dr.end).trim();
    const { start: dateStart, end: dateEnd } = clampDateRange(rawStart, rawEnd);
    const pageIdParam = body.page_id != null ? String(body.page_id).trim() : null;
    const forceRefresh = body.force_refresh === true;
    const now = new Date();

    const resolved = await resolveLinkedInContentForMetrics(admin, organizationId, pageIdParam, {
      allowPerson: true,
    });
    if (!resolved) {
      return linkedinContentJson({ error: "LinkedIn Content not connected or no page configured" }, 400);
    }

    const { accessToken, account } = resolved;
    const pageId = account.page_id;
    const isPerson = isLinkedInPersonAccount(account);

    if (isPerson) {
      const granted = parseLinkedInGrantedScopes(
        (account as { granted_scopes?: unknown }).granted_scopes,
      );
      const missingInsights = missingLinkedInScopesForFeature(granted, "memberInsights");
      if (missingInsights.length > 0) {
        return linkedinContentJson({
          error:
            "Personal LinkedIn insights are not available yet (LinkedIn does not grant r_member_social / r_member_postAnalytics on this app). Select a Company Page for post insights.",
          code: "LINKEDIN_MEMBER_INSIGHTS_UNAVAILABLE",
          missing_scopes: missingInsights,
        }, 400);
      }
    }

    if (!forceRefresh) {
      const { data: cached } = await admin
        .from("linkedin_content_metrics_cache")
        .select("response_json, fetched_at")
        .eq("organization_id", organizationId)
        .eq("page_id", pageId)
        .eq("date_start", dateStart)
        .eq("date_end", dateEnd)
        .eq("metrics_key", METRICS_CACHE_KEY)
        .eq("page_token", "")
        .gt("expires_at", now.toISOString())
        .maybeSingle();
      if (cached?.response_json) {
        return linkedinContentJson({ ...(cached.response_json as object), cached: true }, 200);
      }
    }

    const fetchPostsForToken = async (token: string) => {
      if (isPerson) {
        return {
          posts: await fetchLinkedInMemberPosts(token, pageId, dateStart, dateEnd),
          audienceCount: null as number | null,
        };
      }
      const [orgPosts, followers] = await Promise.all([
        fetchLinkedInOrganizationPosts(token, pageId, dateStart, dateEnd),
        fetchLinkedInFollowerCount(token, pageId),
      ]);
      return { posts: orgPosts, audienceCount: followers };
    };

    let posts;
    let audienceCount: number | null = null;
    try {
      ({ posts, audienceCount } = await fetchPostsForToken(accessToken));
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      console.error("linkedin-content-api getMetrics fetchPosts:", msg);
      if (isPerson && /partnerApiPostsExternal|FINDER-author|Not enough permissions/i.test(msg)) {
        return linkedinContentJson({
          error:
            "Personal LinkedIn insights are not available yet (LinkedIn rejected member post finder). Select a Company Page for post insights.",
          code: "LINKEDIN_MEMBER_INSIGHTS_UNAVAILABLE",
          linkedin_error: msg,
        }, 400);
      }
      if (isLinkedInContentAuthFailure(msg)) {
        // Person OAuth can revoke sibling page tokens; try refresh once before asking reconnect.
        const kind = isPerson ? "person" : "organization";
        const refreshed = await getLinkedInContentAccessToken(admin, organizationId, pageId, {
          forceRefresh: true,
        });
        if (refreshed && refreshed !== accessToken) {
          try {
            ({ posts, audienceCount } = await fetchPostsForToken(refreshed));
          } catch (retryErr) {
            const retryMsg = retryErr instanceof Error ? retryErr.message : String(retryErr);
            console.error("linkedin-content-api getMetrics fetchPosts after refresh:", retryMsg);
            return linkedinContentJson({
              error: linkedInContentReauthErrorMessage(kind),
              code: "LINKEDIN_CONTENT_REAUTH_REQUIRED",
              linkedin_error: retryMsg,
            }, 400);
          }
        } else {
          return linkedinContentJson({
            error: linkedInContentReauthErrorMessage(kind),
            code: "LINKEDIN_CONTENT_REAUTH_REQUIRED",
            linkedin_error: msg,
          }, 400);
        }
      } else {
        return linkedinContentJson({ error: msg, code: "LINKEDIN_CONTENT_API_ERROR" }, 400);
      }
    }

    const links = await loadLinkedInPlanLinks(admin, organizationId);
    const matchIndex = buildPlanMatchIndex(links);
    const planIds = [...new Set(links.map((l) => l.social_media_plan_id))];
    const planMap = await loadPlanDetails(admin, planIds);

    // Finder can lag (esp. video still PROCESSING). Merge Synckerja-published links missing
    // from /rest/posts so Performance stays read-after-write — scoped to this page only.
    const seenPostIds = new Set(posts.map((p) => String(p.id ?? "").trim()).filter(Boolean));
    for (const link of links) {
      const ownedBy = String(link.platform_account_open_id ?? "").trim();
      if (ownedBy && ownedBy !== pageId) continue;
      // Unscoped legacy links: only merge onto the org default page to avoid multi-page bleed.
      if (!ownedBy && !account.is_default) continue;
      const id = String(link.external_post_id ?? "").trim()
        || parseLinkedInPostIdFromUrl(link.url)
        || "";
      if (!id || seenPostIds.has(id)) continue;
      seenPostIds.add(id);
      const plan = planMap.get(link.social_media_plan_id);
      const postedMs = plan?.actual_post_date
        ? new Date(plan.actual_post_date).getTime()
        : Date.now();
      posts.push({
        id,
        title: id,
        published_at: new Date(
          Number.isFinite(postedMs) ? postedMs : Date.now(),
        ).toISOString(),
        thumbnail_url: null,
        view_count: 0,
        like_count: 0,
        comment_count: 0,
        share_count: 0,
      });
    }
    posts.sort((a, b) => {
      const ta = a.published_at ? new Date(a.published_at).getTime() : 0;
      const tb = b.published_at ? new Date(b.published_at).getTime() : 0;
      return tb - ta;
    });

    // Fill impressions for merge stubs (and any finder row still at 0). Soft-fail inside helper.
    const needImpressionIds = posts
      .map((p) => String(p.id ?? "").trim())
      .filter((id, i) => Boolean(id) && !(Number(posts[i]?.view_count) > 0));
    if (needImpressionIds.length > 0) {
      const impressionMap = isPerson
        ? await fetchMemberCreatorPostAnalytics(accessToken, needImpressionIds, "IMPRESSION")
        : await fetchShareImpressionCounts(accessToken, pageId, needImpressionIds);
      for (const post of posts) {
        const id = String(post.id ?? "").trim();
        if (!id || Number(post.view_count) > 0) continue;
        post.view_count = impressionMap.get(id) ?? 0;
      }
    }

    const backfillMatches: Array<{ link_id: string; post_id: string }> = [];
    const rows = posts.map((post) => {
      const match = matchPostToPlan(post, matchIndex, planMap);
      const postId = String(post.id ?? "").trim();
      if (match.link_id && postId && match.match_type) {
        backfillMatches.push({ link_id: match.link_id, post_id: postId });
      }
      const engagementRate = computeEngagementRate(post);
      const postedAt = post.published_at ? new Date(post.published_at).toISOString() : null;

      return {
        post_id: postId,
        title: post.title ?? "",
        share_url: postId ? buildLinkedInPostUrl(postId) : null,
        cover_image_url: post.thumbnail_url ?? null,
        duration: null,
        view_count: post.view_count ?? 0,
        like_count: post.like_count ?? 0,
        comment_count: post.comment_count ?? 0,
        share_count: post.share_count ?? 0,
        engagement_rate: engagementRate,
        posted_at: postedAt,
        plan_id: match.plan_id,
        service_name: match.service_name,
        content_pillar: match.content_pillar,
        pic_name: match.pic_name,
        plan_post_date: match.actual_post_date,
        match_type: match.match_type,
      };
    });

    if (backfillMatches.length > 0) {
      await backfillLinkPostIds(admin, organizationId, pageId, backfillMatches);
    }

    const summary = {
      post_count: rows.length,
      total_views: rows.reduce((s, r) => s + (Number(r.view_count) || 0), 0),
      total_likes: rows.reduce((s, r) => s + (Number(r.like_count) || 0), 0),
      total_comments: rows.reduce((s, r) => s + (Number(r.comment_count) || 0), 0),
      total_shares: rows.reduce((s, r) => s + (Number(r.share_count) || 0), 0),
      avg_engagement_rate: rows.length > 0
        ? rows.reduce((s, r) => s + (Number(r.engagement_rate) || 0), 0) / rows.length
        : null,
      matched_plans: rows.filter((r) => r.plan_id).length,
    };

    const payload = {
      rows,
      summary,
      audience_count: audienceCount,
      page_id: pageId,
      account_id: account.id,
      account_label: account.label || account.display_name,
      date_start: dateStart,
      date_end: dateEnd,
      fetched_at: now.toISOString(),
    };

    const expiresAt = new Date(now.getTime() + CACHE_TTL_MINUTES * 60_000).toISOString();
    await admin.from("linkedin_content_metrics_cache").upsert({
      organization_id: organizationId,
      page_id: pageId,
      date_start: dateStart,
      date_end: dateEnd,
      metrics_key: METRICS_CACHE_KEY,
      page_token: "",
      response_json: payload,
      fetched_at: now.toISOString(),
      expires_at: expiresAt,
    }, {
      onConflict: "organization_id,page_id,date_start,date_end,metrics_key,page_token",
    });

    return linkedinContentJson(payload, 200);
  } catch (unhandled) {
    const msg = unhandled instanceof Error ? unhandled.message : String(unhandled);
    console.error("linkedin-content-api getMetrics unhandled:", msg);
    return linkedinContentJson({ error: msg, code: "INTERNAL_ERROR" }, 500);
  }
}

/** LinkedIn often returns this after a sibling OAuth (e.g. personal) revokes page tokens. */
export const LINKEDIN_AUTH_FAIL_RE =
  /Could not authenticate|Unauthorized|invalid.?token|token.?expired|REVOKED_ACCESS_TOKEN/i;

export function isLinkedInContentAuthFailure(message: string): boolean {
  return LINKEDIN_AUTH_FAIL_RE.test(String(message ?? ""));
}

export function linkedInContentReauthErrorMessage(
  accountKind: "organization" | "person" = "organization",
): string {
  return accountKind === "person"
    ? "LinkedIn personal connection expired or was revoked. Reconnect personal profile in LinkedIn settings, then retry."
    : "LinkedIn connection expired or was revoked. Reconnect this Company Page in LinkedIn settings (after connecting personal, page tokens often need a fresh connect), then retry.";
}

export function mapLinkedInContentAuthFailure(
  message: string,
  accountKind: "organization" | "person" = "organization",
): { error: string; code: "LINKEDIN_CONTENT_REAUTH_REQUIRED"; linkedin_error: string } | null {
  if (!isLinkedInContentAuthFailure(message)) return null;
  return {
    error: linkedInContentReauthErrorMessage(accountKind),
    code: "LINKEDIN_CONTENT_REAUTH_REQUIRED",
    linkedin_error: message,
  };
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { LinkedInPostRow } from "./linkedinContentApi.ts";
import { buildLinkedInPostUrl } from "./linkedinContentApi.ts";

export type PlanMatchInfo = {
  plan_id: string | null;
  service_name: string | null;
  content_pillar: string | null;
  pic_name: string | null;
  actual_post_date: string | null;
  match_type: "share_url" | "post_id" | null;
  link_id: string | null;
};

type LinkRow = {
  id: string;
  url: string;
  external_post_id: string | null;
  social_media_plan_id: string;
  /** LinkedIn page id that published this link (multi-page guard). */
  platform_account_open_id: string | null;
};

type PlanRow = {
  id: string;
  actual_post_date: string | null;
  pic_id: string | null;
  service_id: string | null;
  content_pillar_id: string | null;
  services?: { name?: string } | { name?: string }[] | null;
  content_pillars?: { name?: string } | { name?: string }[] | null;
  employees?: { full_name?: string } | { full_name?: string }[] | null;
};

export function parseLinkedInPostIdFromUrl(url: string): string | null {
  const trimmed = url.trim();
  if (!trimmed) return null;

  const urnPatterns = [
    /urn:li:(?:ugcPost|share|activity):(\d+)/i,
    /feed\/update\/(urn:li:(?:ugcPost|share|activity):\d+)/i,
    /linkedin\.com\/posts\/[^/]+-(\d+)/i,
    /linkedin\.com\/feed\/update\/[^/]*(\d{8,})/i,
  ];
  for (const re of urnPatterns) {
    const m = re.exec(trimmed);
    if (m?.[1]) {
      const id = m[1];
      if (id.startsWith("urn:li:")) return id;
      if (/^\d+$/.test(id)) {
        if (trimmed.includes("ugcPost")) return `urn:li:ugcPost:${id}`;
        if (trimmed.includes("share")) return `urn:li:share:${id}`;
        return `urn:li:activity:${id}`;
      }
      return id;
    }
  }

  try {
    const u = new URL(trimmed);
    const pathMatch = /feed\/update\/(.+)/i.exec(u.pathname);
    if (pathMatch?.[1]) {
      const decoded = decodeURIComponent(pathMatch[1]).replace(/\/+$/, "");
      if (decoded.startsWith("urn:li:")) return decoded;
    }
  } catch {
    // fall through
  }

  return null;
}

function normalizeUrl(url: string): string {
  try {
    const u = new URL(url.trim());
    u.hash = "";
    return u.toString().replace(/\/+$/, "");
  } catch {
    return url.trim().replace(/\/+$/, "");
  }
}

function pickName(rel: { name?: string } | { name?: string }[] | null | undefined): string | null {
  if (!rel) return null;
  if (Array.isArray(rel)) return rel[0]?.name ? String(rel[0].name) : null;
  return rel.name ? String(rel.name) : null;
}

function pickEmployeeName(
  rel: { full_name?: string } | { full_name?: string }[] | null | undefined,
): string | null {
  if (!rel) return null;
  if (Array.isArray(rel)) return rel[0]?.full_name ? String(rel[0].full_name) : null;
  return rel.full_name ? String(rel.full_name) : null;
}

export async function loadLinkedInPlanLinks(
  admin: SupabaseClient,
  organizationId: string,
): Promise<LinkRow[]> {
  const { data: links } = await admin
    .from("social_media_links")
    .select("id, url, external_post_id, social_media_plan_id, platform, platform_account_open_id")
    .ilike("platform", "linkedin");

  const rows = (links ?? []).filter((l) => {
    const platform = String((l as { platform?: string }).platform ?? "").toLowerCase();
    return platform.includes("linkedin");
  }).map((l) => {
    const row = l as LinkRow & { platform_account_open_id?: string | null };
    return {
      id: String(row.id),
      url: String(row.url ?? ""),
      external_post_id: row.external_post_id != null ? String(row.external_post_id) : null,
      social_media_plan_id: String(row.social_media_plan_id),
      platform_account_open_id: row.platform_account_open_id != null
        ? String(row.platform_account_open_id).trim() || null
        : null,
    } satisfies LinkRow;
  });

  if (rows.length === 0) return [];

  const planIds = [...new Set(rows.map((r) => r.social_media_plan_id))];
  const { data: plans } = await admin
    .from("social_media_plans")
    .select("id, organization_id")
    .eq("organization_id", organizationId)
    .in("id", planIds);

  const orgPlanSet = new Set((plans ?? []).map((p) => String((p as { id: string }).id)));
  return rows.filter((r) => orgPlanSet.has(r.social_media_plan_id));
}

export function buildPlanMatchIndex(links: LinkRow[]): {
  byPostId: Map<string, LinkRow>;
  byShareUrl: Map<string, LinkRow>;
} {
  const byPostId = new Map<string, LinkRow>();
  const byShareUrl = new Map<string, LinkRow>();
  for (const link of links) {
    const postId = link.external_post_id?.trim() || parseLinkedInPostIdFromUrl(link.url);
    if (postId) byPostId.set(postId, link);
    byShareUrl.set(normalizeUrl(link.url), link);
  }
  return { byPostId, byShareUrl };
}

export async function loadPlanDetails(
  admin: SupabaseClient,
  planIds: string[],
): Promise<Map<string, PlanRow>> {
  if (planIds.length === 0) return new Map();
  const { data } = await admin
    .from("social_media_plans")
    .select(`
      id,
      actual_post_date,
      pic_id,
      service_id,
      content_pillar_id,
      services ( name ),
      content_pillars ( name )
    `)
    .in("id", planIds);

  const picIds = [...new Set((data ?? []).map((r) => (r as PlanRow).pic_id).filter(Boolean))];
  const picNameById = new Map<string, string>();
  if (picIds.length > 0) {
    const { data: employees } = await admin
      .from("employees")
      .select("id, full_name")
      .in("id", picIds as string[]);
    for (const e of employees ?? []) {
      const id = String((e as { id: string }).id);
      const name = String((e as { full_name?: string }).full_name ?? "").trim();
      if (name) picNameById.set(id, name);
    }
  }

  const map = new Map<string, PlanRow>();
  for (const row of data ?? []) {
    const plan = row as PlanRow;
    const picId = plan.pic_id != null ? String(plan.pic_id) : "";
    if (picId && picNameById.has(picId)) {
      plan.employees = { full_name: picNameById.get(picId) };
    }
    map.set(String(plan.id), plan);
  }
  return map;
}

export function matchPostToPlan(
  post: LinkedInPostRow,
  index: { byPostId: Map<string, LinkRow>; byShareUrl: Map<string, LinkRow> },
  planMap: Map<string, PlanRow>,
): PlanMatchInfo {
  const postId = String(post.id ?? "").trim();
  const shareUrl = postId ? normalizeUrl(buildLinkedInPostUrl(postId)) : "";

  let link: LinkRow | undefined;
  let matchType: PlanMatchInfo["match_type"] = null;

  if (shareUrl && index.byShareUrl.has(shareUrl)) {
    link = index.byShareUrl.get(shareUrl);
    matchType = "share_url";
  } else if (postId && index.byPostId.has(postId)) {
    link = index.byPostId.get(postId);
    matchType = "post_id";
  }

  if (!link) {
    return {
      plan_id: null,
      service_name: null,
      content_pillar: null,
      pic_name: null,
      actual_post_date: null,
      match_type: null,
      link_id: null,
    };
  }

  const plan = planMap.get(link.social_media_plan_id);
  return {
    plan_id: link.social_media_plan_id,
    service_name: pickName(plan?.services ?? null),
    content_pillar: pickName(plan?.content_pillars ?? null),
    pic_name: pickEmployeeName(plan?.employees ?? null),
    actual_post_date: plan?.actual_post_date != null ? String(plan.actual_post_date) : null,
    match_type: matchType,
    link_id: link.id,
  };
}

export function computeEngagementRate(post: LinkedInPostRow): number | null {
  const views = Number(post.view_count ?? 0);
  const likes = Number(post.like_count ?? 0) || 0;
  const comments = Number(post.comment_count ?? 0) || 0;
  const shares = Number(post.share_count ?? 0) || 0;
  const engagements = likes + comments + shares;
  if (views > 0) return (engagements / views) * 100;
  if (engagements > 0) return null;
  return 0;
}

export async function backfillLinkPostIds(
  admin: SupabaseClient,
  organizationId: string,
  pageId: string,
  matches: Array<{ link_id: string; post_id: string }>,
): Promise<void> {
  const now = new Date().toISOString();
  for (const m of matches) {
    const { data: existing } = await admin
      .from("social_media_links")
      .select("platform_account_open_id")
      .eq("id", m.link_id)
      .maybeSingle();
    const ownedBy = String(
      (existing as { platform_account_open_id?: string | null } | null)
        ?.platform_account_open_id ?? "",
    ).trim();
    // Never re-attribute a link owned by another LinkedIn page (multi-page bleed).
    if (ownedBy && ownedBy !== pageId) continue;

    await admin
      .from("social_media_links")
      .update({
        external_post_id: m.post_id,
        platform_account_open_id: pageId,
        last_insights_sync_at: now,
      })
      .eq("id", m.link_id);
  }
}

