function parsePostBaselines(body: Record<string, unknown>) {
  const raw = body.posts;
  if (!Array.isArray(raw)) return [];
  return raw
    .map((row) => {
      const item = row as Record<string, unknown>;
      const post_id = String(item.post_id ?? item.media_id ?? item.id ?? "").trim();
      const comment_count = Number(item.comment_count ?? 0);
      if (!post_id) return null;
      return { post_id, comment_count: Number.isFinite(comment_count) ? comment_count : 0 };
    })
    .filter((row): row is { post_id: string; comment_count: number } => row != null);
}

function parseCommentIds(body: Record<string, unknown>): string[] {
  const raw = body.comment_ids;
  if (!Array.isArray(raw)) return [];
  return raw.map((id) => String(id).trim()).filter(Boolean);
}

function defaultDateRange(): { start: string; end: string } {
  const end = new Date();
  const start = new Date();
  start.setDate(start.getDate() - 364);
  const fmt = (d: Date) => {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    return `${y}-${m}-${day}`;
  };
  return { start: fmt(start), end: fmt(end) };
}

export async function handleLinkedInComments(
  admin: SupabaseClient,
  userId: string,
  body: Record<string, unknown>,
): Promise<Response> {
  try {
    const platformForbidden = requireLinkedInContentPlatformConfigured();
    if (platformForbidden) return platformForbidden;

    const action = String(body.action ?? "").trim();
    const organizationId = String(body.organization_id ?? "").trim();
    const pageId = String(body.page_id ?? body.account_id ?? "").trim();
    if (!organizationId) return linkedinContentJson({ error: "Missing organization_id" }, 400);

    const orgForbidden = await requireActiveOrg(admin, userId, organizationId);
    if (orgForbidden) return orgForbidden;

    if (action === "getInboxState") {
      if (!pageId) return linkedinContentJson({ error: "Missing page_id" }, 400);
      const state = await getLinkedInManageCommentsInboxState(admin, organizationId, pageId);
      return linkedinContentJson(state, 200);
    }

    if (action === "syncPostBaselines") {
      if (!pageId) return linkedinContentJson({ error: "Missing page_id" }, 400);
      const posts = parsePostBaselines(body);
      const state = await syncLinkedInManageCommentsPostBaselines(admin, organizationId, pageId, posts);
      return linkedinContentJson(state, 200);
    }

    if (action === "syncInboundComments") {
      if (!pageId) return linkedinContentJson({ error: "Missing page_id" }, 400);
      const postId = String(body.post_id ?? body.media_id ?? "").trim();
      if (!postId) return linkedinContentJson({ error: "Missing post_id" }, 400);
      const commentIds = parseCommentIds(body);
      const state = await syncLinkedInManageCommentsInboundComments(
        admin, organizationId, pageId, postId, commentIds,
      );
      return linkedinContentJson(state, 200);
    }

    if (action === "dismissPostHighlight") {
      if (!pageId) return linkedinContentJson({ error: "Missing page_id" }, 400);
      const postId = String(body.post_id ?? body.media_id ?? "").trim();
      if (!postId) return linkedinContentJson({ error: "Missing post_id" }, 400);
      const state = await dismissLinkedInManageCommentsPostHighlight(
        admin, organizationId, pageId, postId,
      );
      return linkedinContentJson(state, 200);
    }

    if (action === "markCommentEngaged") {
      if (!pageId) return linkedinContentJson({ error: "Missing page_id" }, 400);
      const postId = String(body.post_id ?? body.media_id ?? "").trim();
      const commentId = String(body.comment_id ?? "").trim();
      if (!postId || !commentId) {
        return linkedinContentJson({ error: "Missing post_id or comment_id" }, 400);
      }
      const state = await markLinkedInManageCommentsCommentRead(
        admin, organizationId, pageId, postId, commentId, userId,
      );
      return linkedinContentJson({ ok: true, ...state }, 200);
    }

    if (!pageId) return linkedinContentJson({ error: "Missing page_id" }, 400);
    const resolved = await resolveOrgLinkedInContentForMetrics(admin, organizationId, pageId);
    if (!resolved) {
      return linkedinContentJson({ error: "LinkedIn page not connected" }, 404);
    }

    const { accessToken, account } = resolved;
    const resolvedPageId = account.page_id;

    if (action === "sync_posts" || action === "listPosts" || action === "getCommentPosts") {
      const dr = defaultDateRange();
      try {
        const posts = await fetchLinkedInOrganizationPosts(
          accessToken,
          resolvedPageId,
          dr.start,
          dr.end,
        );
        return linkedinContentJson({
          posts: posts.map((p) => ({
            id: String(p.id ?? ""),
            media_id: String(p.id ?? ""),
            post_id: String(p.id ?? ""),
            caption: p.title ?? "",
            title: p.title ?? "",
            thumbnail_url: p.thumbnail_url ?? null,
            cover_image_url: p.thumbnail_url ?? null,
            permalink: p.id ? `https://www.linkedin.com/feed/update/${encodeURIComponent(String(p.id))}/` : null,
            share_url: p.id ? `https://www.linkedin.com/feed/update/${encodeURIComponent(String(p.id))}/` : null,
            timestamp: p.published_at,
            posted_at: p.published_at,
            comment_count: p.comment_count ?? 0,
            like_count: p.like_count ?? 0,
          })),
          page_id: resolvedPageId,
          account_id: account.id,
          account_label: account.label || account.display_name,
        }, 200);
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        return linkedInCommentsApiError(msg, action);
      }
    }

    if (action === "sync_comments" || action === "listComments") {
      const postId = String(body.post_id ?? body.media_id ?? "").trim();
      if (!postId) return linkedinContentJson({ error: "Missing post_id" }, 400);
      const sort = String(body.sort ?? "newest");
      try {
        const comments = await fetchAndHydrateComments(
          accessToken,
          postId,
          resolvedPageId,
          account,
        );
        const topLevel = comments.filter((c) => !c.parent_comment_id);
        return linkedinContentJson({
          comments: sortComments(topLevel.map(mapCommentRow), sort),
          page_id: resolvedPageId,
        }, 200);
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        return linkedInCommentsApiError(msg, action);
      }
    }

    if (action === "listReplies") {
      const postId = String(body.post_id ?? body.media_id ?? "").trim();
      const commentId = String(body.comment_id ?? "").trim();
      if (!postId || !commentId) {
        return linkedinContentJson({ error: "Missing post_id or comment_id" }, 400);
      }
      const sort = String(body.sort ?? "newest");
      try {
        const comments = await fetchAndHydrateComments(
          accessToken,
          postId,
          resolvedPageId,
          account,
        );
        const replies = comments.filter((c) => c.parent_comment_id === commentId);
        return linkedinContentJson({ comments: sortComments(replies.map(mapCommentRow), sort) }, 200);
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        return linkedInCommentsApiError(msg, action);
      }
    }

    if (action === "reply" || action === "replyComment") {
      const postId = String(body.post_id ?? body.media_id ?? "").trim();
      const text = String(body.text ?? "").trim();
      const commentId = String(body.comment_id ?? "").trim();
      if (!postId || !text || !commentId) {
        return linkedinContentJson({ error: "Missing post_id, comment_id, or text" }, 400);
      }
      try {
        const reply = await replyLinkedInComment(
          accessToken, postId, resolvedPageId, commentId, text,
        );
        const inboxState = await markLinkedInManageCommentsCommentRead(
          admin, organizationId, resolvedPageId, postId, commentId, userId,
        );
        return linkedinContentJson({
          ok: true,
          comment_id: reply.id,
          ...inboxState,
        }, 200);
      } catch (e) {
        const msg = e instanceof Error ? e.message : String(e);
        return linkedInCommentsApiError(msg, action);
      }
    }

    return linkedinContentJson({ error: "Unknown action", action }, 400);
  } catch (unhandled) {
    const msg = unhandled instanceof Error ? unhandled.message : String(unhandled);
    console.error("linkedin-content-api comments unhandled:", msg);
    return linkedinContentJson({ error: msg, code: "INTERNAL_ERROR" }, 500);
  }
}

import {
  encodeLinkedInRestliUrn,
  linkedInRestGet,
  parseOrganizationIdFromUrn,
  type LinkedInContentComment,
} from "./linkedinContentApi.ts";

export type LinkedInCommentAuthorHydrateContext = {
  accessToken: string;
  pageUrn: string;
  pageLabel: string;
  pageThumbnailUrl: string | null;
};

type AuthorProfile = {
  displayName: string;
  avatarUrl: string | null;
};

const PERSON_FALLBACK = "LinkedIn member";

function parsePersonIdFromUrn(urn: string): string | null {
  const m = /^urn:li:person:([^:\s]+)$/i.exec(String(urn ?? "").trim());
  return m?.[1] ?? null;
}

function parseOrgOrBrandIdFromUrn(urn: string): string | null {
  const fromOrg = parseOrganizationIdFromUrn(urn);
  if (fromOrg) return fromOrg;
  const m = /^urn:li:organizationBrand:(\d+)$/i.exec(String(urn ?? "").trim());
  return m?.[1] ?? null;
}

function isRawUrn(value: string | null | undefined): boolean {
  return /^urn:li:/i.test(String(value ?? "").trim());
}

async function fetchOrganizationProfile(
  accessToken: string,
  orgId: string,
): Promise<AuthorProfile | null> {
  try {
    const org = await linkedInRestGet<{
      localizedName?: string;
      logoV2?: {
        "original~"?: { elements?: Array<{ identifiers?: Array<{ identifier?: string }> }> };
      };
    }>(accessToken, `/rest/organizations/${encodeURIComponent(orgId)}`);
    const displayName = String(org?.localizedName ?? "").trim();
    if (!displayName) return null;
    let avatarUrl: string | null = null;
    const logoElements = org?.logoV2?.["original~"]?.elements;
    if (logoElements?.[0]?.identifiers?.[0]?.identifier) {
      avatarUrl = String(logoElements[0].identifiers[0].identifier);
    }
    return { displayName, avatarUrl };
  } catch (e) {
    console.warn(
      "linkedinCommentAuthorHydrate org:",
      orgId,
      e instanceof Error ? e.message : e,
    );
    return null;
  }
}

async function fetchPersonProfile(
  accessToken: string,
  personId: string,
): Promise<AuthorProfile | null> {
  try {
    // Rest.li composite key: /rest/people/(id:{personId})
    const key = encodeLinkedInRestliUrn(`(id:${personId})`);
    const person = await linkedInRestGet<{
      localizedFirstName?: string;
      localizedLastName?: string;
      id?: string;
    }>(
      accessToken,
      `/rest/people/${key}`,
      { fields: "localizedFirstName,localizedLastName,id" },
    );
    if (String(person?.id ?? "").toLowerCase() === "private") {
      return { displayName: PERSON_FALLBACK, avatarUrl: null };
    }
    const first = String(person?.localizedFirstName ?? "").trim();
    const last = String(person?.localizedLastName ?? "").trim();
    const displayName = [first, last].filter(Boolean).join(" ").trim();
    if (!displayName) return { displayName: PERSON_FALLBACK, avatarUrl: null };
    return { displayName, avatarUrl: null };
  } catch (e) {
    console.warn(
      "linkedinCommentAuthorHydrate person:",
      personId,
      e instanceof Error ? e.message : e,
    );
    return { displayName: PERSON_FALLBACK, avatarUrl: null };
  }
}

/**
 * Resolve author_name / author_avatar_url from actor_urn.
 * Soft-fails per actor; never leaves a raw URN in author_name.
 */
export async function hydrateLinkedInCommentAuthors(
  comments: LinkedInContentComment[],
  ctx: LinkedInCommentAuthorHydrateContext,
): Promise<LinkedInContentComment[]> {
  if (comments.length === 0) return comments;

  const pageLabel = String(ctx.pageLabel ?? "").trim() || "LinkedIn Page";
  const profiles = new Map<string, AuthorProfile>();

  // Owner shortcut — no LinkedIn round-trip.
  profiles.set(ctx.pageUrn, {
    displayName: pageLabel,
    avatarUrl: ctx.pageThumbnailUrl,
  });

  const uniqueActors = [
    ...new Set(
      comments
        .map((c) => String(c.actor_urn ?? "").trim())
        .filter((urn) => urn && urn !== ctx.pageUrn),
    ),
  ];

  const orgIds = new Set<string>();
  const personIds = new Set<string>();
  for (const urn of uniqueActors) {
    const orgId = parseOrgOrBrandIdFromUrn(urn);
    if (orgId) {
      orgIds.add(orgId);
      continue;
    }
    const personId = parsePersonIdFromUrn(urn);
    if (personId) personIds.add(personId);
  }

  await Promise.all([
    ...[...orgIds].map(async (orgId) => {
      const profile = await fetchOrganizationProfile(ctx.accessToken, orgId);
      if (!profile) return;
      profiles.set(`urn:li:organization:${orgId}`, profile);
      profiles.set(`urn:li:organizationBrand:${orgId}`, profile);
    }),
    ...[...personIds].map(async (personId) => {
      const profile = await fetchPersonProfile(ctx.accessToken, personId);
      if (!profile) return;
      profiles.set(`urn:li:person:${personId}`, profile);
    }),
  ]);

  return comments.map((c) => {
    const actor = String(c.actor_urn ?? "").trim();
    const profile = actor ? profiles.get(actor) : undefined;
    let authorName = profile?.displayName?.trim() || null;
    if (isRawUrn(authorName)) authorName = PERSON_FALLBACK;
    if (!authorName && actor) {
      if (parsePersonIdFromUrn(actor)) authorName = PERSON_FALLBACK;
      else if (parseOrgOrBrandIdFromUrn(actor)) {
        authorName = `LinkedIn ${parseOrgOrBrandIdFromUrn(actor)}`;
      }
    }
    return {
      ...c,
      author_name: authorName,
      author_avatar_url: profile?.avatarUrl ?? c.author_avatar_url ?? null,
    };
  });
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

export type LinkedInInboxPostStateRow = {
  post_id: string;
  last_known_comment_count: number;
  is_highlighted: boolean;
  pinned_at: string | null;
};

export type LinkedInInboxInboundCommentRow = {
  post_id: string;
  comment_id: string;
  detected_at: string;
};

export type LinkedInManageCommentsInboxState = {
  posts: LinkedInInboxPostStateRow[];
  inbound_comments: LinkedInInboxInboundCommentRow[];
  engaged_comment_ids: string[];
};

type PostBaselineInput = { post_id: string; comment_count: number };

export async function getLinkedInManageCommentsInboxState(
  admin: SupabaseClient,
  organizationId: string,
  pageId: string,
): Promise<LinkedInManageCommentsInboxState> {
  const [postsRes, inboundRes, engagedRes] = await Promise.all([
    admin.from("linkedin_manage_comments_post_inbox_state").select("*")
      .eq("organization_id", organizationId).eq("page_id", pageId),
    admin.from("linkedin_manage_comments_inbound_comments").select("*")
      .eq("organization_id", organizationId).eq("page_id", pageId),
    admin.from("linkedin_manage_comments_comment_engagements").select("comment_id")
      .eq("organization_id", organizationId).eq("page_id", pageId),
  ]);
  if (postsRes.error) throw new Error(postsRes.error.message);
  if (inboundRes.error) throw new Error(inboundRes.error.message);
  if (engagedRes.error) throw new Error(engagedRes.error.message);

  return {
    posts: (postsRes.data ?? []).map((row) => ({
      post_id: String(row.post_id),
      last_known_comment_count: Number(row.last_known_comment_count ?? 0),
      is_highlighted: Boolean(row.is_highlighted),
      pinned_at: row.pinned_at ?? null,
    })),
    inbound_comments: (inboundRes.data ?? []).map((row) => ({
      post_id: String(row.post_id),
      comment_id: String(row.comment_id),
      detected_at: String(row.detected_at),
    })),
    engaged_comment_ids: (engagedRes.data ?? []).map((row) => String(row.comment_id)),
  };
}

async function clearInboundForPosts(
  admin: SupabaseClient,
  organizationId: string,
  pageId: string,
  postIds: string[],
): Promise<void> {
  if (postIds.length === 0) return;
  const { error } = await admin
    .from("linkedin_manage_comments_inbound_comments")
    .delete()
    .eq("organization_id", organizationId)
    .eq("page_id", pageId)
    .in("post_id", postIds);
  if (error) throw new Error(error.message);
}

export async function syncLinkedInManageCommentsPostBaselines(
  admin: SupabaseClient,
  organizationId: string,
  pageId: string,
  posts: PostBaselineInput[],
): Promise<LinkedInManageCommentsInboxState> {
  if (posts.length === 0) {
    return getLinkedInManageCommentsInboxState(admin, organizationId, pageId);
  }

  const postIds = posts.map((p) => p.post_id);
  const { data: existingRows, error: fetchErr } = await admin
    .from("linkedin_manage_comments_post_inbox_state")
    .select("*")
    .eq("organization_id", organizationId)
    .eq("page_id", pageId)
    .in("post_id", postIds);
  if (fetchErr) throw new Error(fetchErr.message);

  const existingByPost = new Map((existingRows ?? []).map((row) => [String(row.post_id), row]));
  const now = new Date().toISOString();

  const upserts = posts.map((post) => {
    const prev = existingByPost.get(post.post_id);
    const prevCount = prev != null ? Number(prev.last_known_comment_count ?? 0) : null;
    const countIncreased = prevCount != null && post.comment_count > prevCount;
    const isNew = prev == null;
    let isHighlighted = Boolean(prev?.is_highlighted);
    let pinnedAt: string | null = prev?.pinned_at ?? null;
    if (post.comment_count === 0) {
      isHighlighted = false;
      pinnedAt = null;
    } else if (countIncreased) {
      isHighlighted = true;
      pinnedAt = now;
    } else if (isNew && post.comment_count > 0) {
      isHighlighted = false;
    }
    return {
      organization_id: organizationId,
      page_id: pageId,
      post_id: post.post_id,
      last_known_comment_count: post.comment_count,
      is_highlighted: isHighlighted,
      pinned_at: pinnedAt,
      updated_at: now,
    };
  });

  const { error: upsertErr } = await admin
    .from("linkedin_manage_comments_post_inbox_state")
    .upsert(upserts, { onConflict: "organization_id,page_id,post_id" });
  if (upsertErr) throw new Error(upsertErr.message);

  await clearInboundForPosts(
    admin,
    organizationId,
    pageId,
    posts.filter((p) => p.comment_count === 0).map((p) => p.post_id),
  );

  return getLinkedInManageCommentsInboxState(admin, organizationId, pageId);
}

export async function syncLinkedInManageCommentsInboundComments(
  admin: SupabaseClient,
  organizationId: string,
  pageId: string,
  postId: string,
  commentIds: string[],
): Promise<LinkedInManageCommentsInboxState> {
  const uniqueIds = [...new Set(commentIds.map((id) => id.trim()).filter(Boolean))];
  const now = new Date().toISOString();

  if (uniqueIds.length === 0) {
    await clearInboundForPosts(admin, organizationId, pageId, [postId]);
    const { data: postRow } = await admin
      .from("linkedin_manage_comments_post_inbox_state")
      .select("last_known_comment_count")
      .eq("organization_id", organizationId)
      .eq("page_id", pageId)
      .eq("post_id", postId)
      .maybeSingle();
    await admin.from("linkedin_manage_comments_post_inbox_state").upsert({
      organization_id: organizationId,
      page_id: pageId,
      post_id: postId,
      last_known_comment_count: Number(postRow?.last_known_comment_count ?? 0),
      is_highlighted: false,
      pinned_at: null,
      updated_at: now,
    }, { onConflict: "organization_id,page_id,post_id" });
    return getLinkedInManageCommentsInboxState(admin, organizationId, pageId);
  }

  const rows = uniqueIds.map((commentId) => ({
    organization_id: organizationId,
    page_id: pageId,
    post_id: postId,
    comment_id: commentId,
    detected_at: now,
  }));
  const { error } = await admin
    .from("linkedin_manage_comments_inbound_comments")
    .upsert(rows, { onConflict: "organization_id,page_id,post_id,comment_id", ignoreDuplicates: true });
  if (error) throw new Error(error.message);

  await admin.from("linkedin_manage_comments_post_inbox_state").upsert({
    organization_id: organizationId,
    page_id: pageId,
    post_id: postId,
    is_highlighted: true,
    pinned_at: now,
    updated_at: now,
  }, { onConflict: "organization_id,page_id,post_id" });

  return getLinkedInManageCommentsInboxState(admin, organizationId, pageId);
}

export async function dismissLinkedInManageCommentsPostHighlight(
  admin: SupabaseClient,
  organizationId: string,
  pageId: string,
  postId: string,
): Promise<LinkedInManageCommentsInboxState> {
  const now = new Date().toISOString();
  const { data: postRow } = await admin
    .from("linkedin_manage_comments_post_inbox_state")
    .select("last_known_comment_count")
    .eq("organization_id", organizationId)
    .eq("page_id", pageId)
    .eq("post_id", postId)
    .maybeSingle();

  await admin.from("linkedin_manage_comments_post_inbox_state").upsert({
    organization_id: organizationId,
    page_id: pageId,
    post_id: postId,
    last_known_comment_count: Number(postRow?.last_known_comment_count ?? 0),
    is_highlighted: false,
    pinned_at: null,
    updated_at: now,
  }, { onConflict: "organization_id,page_id,post_id" });

  return getLinkedInManageCommentsInboxState(admin, organizationId, pageId);
}

export async function markLinkedInManageCommentsCommentRead(
  admin: SupabaseClient,
  organizationId: string,
  pageId: string,
  postId: string,
  commentId: string,
  userId: string,
): Promise<LinkedInManageCommentsInboxState> {
  const now = new Date().toISOString();
  await admin.from("linkedin_manage_comments_comment_engagements").upsert({
    organization_id: organizationId,
    page_id: pageId,
    post_id: postId,
    comment_id: commentId,
    engaged_by: userId,
    engaged_at: now,
  }, { onConflict: "organization_id,page_id,post_id,comment_id" });

  await admin
    .from("linkedin_manage_comments_inbound_comments")
    .delete()
    .eq("organization_id", organizationId)
    .eq("page_id", pageId)
    .eq("post_id", postId)
    .eq("comment_id", commentId);

  return getLinkedInManageCommentsInboxState(admin, organizationId, pageId);
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import {
  LINKEDIN_CONTENT_OAUTH_RETURN_PATHS,
  linkedinContentOAuthScopes,
  linkedinContentMemberOAuthScopes,
  parseLinkedInConnectKind,
  readPlatformLinkedInContentOAuth,
  requireOrgAdmin,
  requireLinkedInContentPlatformConfigured,
  linkedinContentJson,
  linkedinContentOAuthRedirectUri,
} from "../../_shared/linkedinContentAuth.ts";

function randomUrlSafe(bytes: number): string {
  const arr = new Uint8Array(bytes);
  crypto.getRandomValues(arr);
  return btoa(String.fromCharCode(...arr))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
}

export async function handleLinkedInOAuthStart(
  admin: SupabaseClient,
  userId: string,
  body: Record<string, unknown>,
): Promise<Response> {
  const platformForbidden = requireLinkedInContentPlatformConfigured();
  if (platformForbidden) return platformForbidden;

  const oauth = readPlatformLinkedInContentOAuth()!;
  const organizationId = String(body.organization_id ?? "").trim();
  if (!organizationId) return linkedinContentJson({ error: "Missing organization_id" }, 400);

  const forbidden = await requireOrgAdmin(admin, userId, organizationId);
  if (forbidden) return forbidden;

  const returnPathRaw = body.return_path != null ? String(body.return_path).trim() : "";
  const returnPath = LINKEDIN_CONTENT_OAUTH_RETURN_PATHS.has(returnPathRaw) ? returnPathRaw : null;
  const connectKind = parseLinkedInConnectKind(body.connect_kind);

  const stateToken = randomUrlSafe(32);
  const expiresAt = new Date(Date.now() + 15 * 60 * 1000).toISOString();

  const { error: stateErr } = await admin.from("linkedin_content_oauth_states").insert({
    organization_id: organizationId,
    user_id: userId,
    state_token: stateToken,
    expires_at: expiresAt,
    connect_kind: connectKind,
    ...(returnPath ? { return_path: returnPath } : {}),
  });
  if (stateErr) {
    console.error("linkedin-content-api oauthStart:", stateErr.message);
    return linkedinContentJson({ error: "Failed to start OAuth" }, 500);
  }

  const redirectUri = linkedinContentOAuthRedirectUri();
  const scope = connectKind === "person"
    ? linkedinContentMemberOAuthScopes()
    : linkedinContentOAuthScopes();
  const params = new URLSearchParams({
    response_type: "code",
    client_id: oauth.clientId,
    redirect_uri: redirectUri,
    state: stateToken,
    scope,
  });

  return linkedinContentJson({
    url: `https://www.linkedin.com/oauth/v2/authorization?${params.toString()}`,
  }, 200);
}

import { encryptLinkedInContentToken } from "../../_shared/linkedinContentConfigCrypto.ts";
import { saveLinkedInPageConnection } from "../../_shared/linkedinContentConnectionSave.ts";
import {
  linkedinContentOAuthScopes,
  linkedinContentMemberOAuthScopes,
  parseLinkedInConnectKind,
} from "../../_shared/linkedinContentAuth.ts";
import {
  LINKEDIN_CONTENT_OAUTH_RETURN_PATHS,
  appPublicOrigin,
  readPlatformLinkedInContentOAuth,
  linkedinContentOAuthRedirectUri,
} from "../../_shared/linkedinContentAuth.ts";
import {
  exchangeLinkedInContentAuthCode,
  fetchLinkedInAdministeredPages,
  fetchLinkedInAuthenticatedMember,
} from "../../_shared/linkedinContentApi.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

function redirectToAppPath(path: string, query: string, status = 302): Response {
  const origin = appPublicOrigin() || "http://localhost:5173";
  const normalizedPath = path.startsWith("/") ? path : `/${path}`;
  return new Response(null, {
    status,
    headers: { Location: `${origin}${normalizedPath}${query}` },
  });
}

function resolveOAuthReturnPath(stored: string | null | undefined): string {
  const path = String(stored ?? "").trim();
  if (path && LINKEDIN_CONTENT_OAUTH_RETURN_PATHS.has(path)) return path;
  return "/digital-marketing/social-media-performance/linkedin/settings";
}

function sanitizeOAuthError(msg: string): string {
  const trimmed = msg.trim();
  if (!trimmed || trimmed === "OK" || trimmed === "ok") return "token_exchange_failed";
  return trimmed;
}

export async function handleLinkedInOAuthCallback(req: Request): Promise<Response> {
  const url = new URL(req.url);
  const authCode = url.searchParams.get("code")?.trim() ?? "";
  const state = url.searchParams.get("state")?.trim() ?? "";
  const oauthError = url.searchParams.get("error")?.trim() ?? "";

  const redirectDefault = (query: string, returnPath?: string | null) =>
    redirectToAppPath(resolveOAuthReturnPath(returnPath), query);

  if (oauthError) {
    const errorDesc = url.searchParams.get("error_description")?.trim() ?? "";
    const query = new URLSearchParams({ oauth_error: oauthError });
    if (errorDesc) query.set("oauth_error_desc", errorDesc);
    return redirectDefault(`?${query.toString()}`);
  }
  if (!authCode || !state) {
    return redirectDefault("?oauth_error=missing_code_or_state");
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL") ?? "";
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
  if (!supabaseUrl || !serviceRoleKey) {
    return redirectDefault("?oauth_error=server_misconfigured");
  }

  const oauth = readPlatformLinkedInContentOAuth();
  if (!oauth) {
    return redirectDefault("?oauth_error=oauth_not_configured");
  }

  const admin = createClient(supabaseUrl, serviceRoleKey);

  const { data: stateRow, error: stateErr } = await admin
    .from("linkedin_content_oauth_states")
    .select("id, organization_id, user_id, expires_at, return_path, connect_kind")
    .eq("state_token", state)
    .maybeSingle();

  const oauthReturnPath = resolveOAuthReturnPath(
    stateRow?.return_path != null ? String(stateRow.return_path) : null,
  );
  const connectKind = parseLinkedInConnectKind(
    (stateRow as { connect_kind?: string } | null)?.connect_kind,
  );

  if (stateErr || !stateRow?.id) {
    return redirectDefault("?oauth_error=invalid_state", oauthReturnPath);
  }

  const expiresAt = new Date(String(stateRow.expires_at)).getTime();
  if (!Number.isFinite(expiresAt) || expiresAt < Date.now()) {
    await admin.from("linkedin_content_oauth_states").delete().eq("id", stateRow.id);
    return redirectDefault("?oauth_error=state_expired", oauthReturnPath);
  }

  await admin.from("linkedin_content_oauth_states").delete().eq("id", stateRow.id);

  const redirectUri = linkedinContentOAuthRedirectUri();
  let tokenData;
  try {
    tokenData = await exchangeLinkedInContentAuthCode(
      oauth.clientId,
      oauth.clientSecret,
      authCode,
      redirectUri,
    );
  } catch (e) {
    const msg = sanitizeOAuthError(e instanceof Error ? e.message : "token_exchange_failed");
    console.error("linkedin-content-api oauth callback:", msg);
    return redirectDefault(`?oauth_error=${encodeURIComponent(msg)}`, oauthReturnPath);
  }

  const organizationId = String(stateRow.organization_id);
  const userId = String(stateRow.user_id);

  if (connectKind === "person") {
    let member;
    try {
      member = await fetchLinkedInAuthenticatedMember(tokenData.access_token);
    } catch (e) {
      const msg = sanitizeOAuthError(e instanceof Error ? e.message : "no_linkedin_member");
      console.error("linkedin-content-api oauth callback member:", msg);
      return redirectDefault(
        `?oauth_error=${encodeURIComponent(msg || "no_linkedin_member")}`,
        oauthReturnPath,
      );
    }

    const grantedScopes = linkedinContentMemberOAuthScopes().split(/\s+/).filter(Boolean);
    try {
      const { isExistingAccount } = await saveLinkedInPageConnection(admin, {
        organizationId,
        userId,
        page: member,
        accessToken: tokenData.access_token,
        refreshToken: tokenData.refresh_token,
        expiresIn: tokenData.expires_in,
        grantedScopes,
        accountKind: "person",
      });
      const query = new URLSearchParams({ connected: "1", connect_kind: "person" });
      if (isExistingAccount) query.set("existing", "1");
      return redirectDefault(`?${query.toString()}`, oauthReturnPath);
    } catch (e) {
      console.error("linkedin-content-api oauth callback save member:", e);
      return redirectDefault("?oauth_error=save_connection_failed", oauthReturnPath);
    }
  }

  let pages;
  try {
    pages = await fetchLinkedInAdministeredPages(tokenData.access_token);
  } catch (e) {
    const msg = sanitizeOAuthError(e instanceof Error ? e.message : "pages_list_failed");
    console.error("linkedin-content-api oauth callback pages:", msg);
    return redirectDefault(`?oauth_error=${encodeURIComponent(msg)}`, oauthReturnPath);
  }

  if (pages.length === 0) {
    return redirectDefault("?oauth_error=no_linkedin_pages", oauthReturnPath);
  }

  const grantedScopes = linkedinContentOAuthScopes().split(/\s+/).filter(Boolean);

  if (pages.length === 1) {
    try {
      const { isExistingAccount } = await saveLinkedInPageConnection(admin, {
        organizationId,
        userId,
        page: pages[0],
        accessToken: tokenData.access_token,
        refreshToken: tokenData.refresh_token,
        expiresIn: tokenData.expires_in,
        grantedScopes,
        accountKind: "organization",
      });
      const query = isExistingAccount ? "?connected=1&existing=1" : "?connected=1";
      return redirectDefault(query, oauthReturnPath);
    } catch (e) {
      console.error("linkedin-content-api oauth callback save:", e);
      return redirectDefault("?oauth_error=save_connection_failed", oauthReturnPath);
    }
  }

  const pendingExpires = new Date(Date.now() + 15 * 60 * 1000).toISOString();
  let accessEnc: string;
  let refreshEnc: string;
  try {
    accessEnc = await encryptLinkedInContentToken(tokenData.access_token);
    refreshEnc = await encryptLinkedInContentToken(tokenData.refresh_token);
  } catch (e) {
    console.error("linkedin-content-api oauth callback encrypt:", e);
    return redirectDefault("?oauth_error=encryption_failed", oauthReturnPath);
  }

  await admin.from("linkedin_content_pending_connections")
    .delete()
    .eq("organization_id", organizationId)
    .eq("user_id", userId);

  const accessExpires = tokenData.expires_in
    ? new Date(Date.now() + tokenData.expires_in * 1000).toISOString()
    : null;

  const { error: pendingErr } = await admin.from("linkedin_content_pending_connections").insert({
    organization_id: organizationId,
    user_id: userId,
    access_token_enc: accessEnc,
    refresh_token_enc: refreshEnc,
    access_token_expires_at: accessExpires,
    pages_json: pages,
    expires_at: pendingExpires,
  });

  if (pendingErr) {
    console.error("linkedin-content-api oauth callback pending:", pendingErr.message);
    return redirectDefault("?oauth_error=save_pending_failed", oauthReturnPath);
  }

  return redirectDefault("?select_page=1", oauthReturnPath);
}
